(.3,.55,.35),([-.95,.99],[-.6,1],[0,.98]),('Biomedical/habitat capacity permits conditional access with local differences.','Non-Lunar human-derived resident/market agency is central.','Useful active-person roles remain; medical capability and stored patterns are not participation.'),
