for r in records:
 changes.append(change(D,'societies',r));changes.append(change(D,'decisions',retained_decision(r,r['qualification_basis'])))
for cid,target,reason in [
 ('c0789','rolltown-us-meritocracy','Shyler-Dome’s housing and service management operates inside the already-retained Bat Hardin national NIT/Meritocracy model. The source explicitly links the returning protagonist and same guaranteed-income economy; a new building and local service jobs do not create a second national productive/access regime.'),
 ('c0790','rolltown-us-meritocracy','The Bat Hardin communes use the same automation/computer-supported assistance economy already retained under Rolltown. The source’s varied lifestyle communities and selected jobs do not identify a second distinct productive-ownership/guarantee arrangement to count.'),
 ('c0791','reynolds-looking-backward','The author’s sequel introduction elaborates the already-retained Reynolds commonwealth. No distinct implemented later material reform is identified in the bounded preview; the sequel title does not add a second economy.'),
]:
 d=deepcopy(D['decisions'][cid]);d.update(status='duplicate',duplicate_of=target,reason=reason,assessment_mode='best_guess',reassessed_on=DATE,current_policy_review=True,follow_up='Completed: link the shared material baseline; distinct scenes and narrative details are not asserted identical.')
 changes.append(change(D,'decisions',d))
write_revision(47,changes,'Twelve later-discovery models from fifteen holds; link three shared Reynolds welfare baselines, distinguish machine versus biological production, correct false public-income guesses and explicitly project the Mechasm horizon.')
